export const transactions = [
 {id:1,payee:'Corner shop',category:'Food',amountPence:-1250},
 {id:2,payee:'Monthly salary',category:'Income',amountPence:240000},
 {id:3,payee:'City transport',category:'Travel',amountPence:-480},
 {id:4,payee:'Weekly groceries',category:'Food',amountPence:-4235}
];
export const modules = ['How applications work','JavaScript for data','A page that responds','Thinking in React','Understand the build','TypeScript as feedback','Data across a network','Tables with TanStack','Independent project'];
export const lessons = [
 {title:'Meet the moving parts',tag:'The big picture',time:6,question:'What actually happens when you filter a transaction list?',body:'An application connects data, decisions and a screen. Your transaction records are data. “Show Food” is a decision the user makes. The visible rows are the result. A filter can run entirely in the browser when those records are already loaded.',why:'Before choosing a framework, learn to follow a change from its input to its visible result.',experiment:'Choose a category in the finance preview. Watch the rows and subtotal change together.',task:'With the records already loaded, where can this category filter run?',choices:['In the browser','Only in PostgreSQL','Only in Python'],answer:0,explain:'The browser already has these four records. JavaScript can filter them without contacting a server. Large datasets may need server-side filtering instead.',hint:'Does the browser need any new records for this example?',visual:'filter'},
 {title:'Structure, style, behaviour',tag:'The browser',time:7,question:'Why does a page need three different ingredients?',body:'HTML describes structure: headings, buttons and table rows. CSS describes presentation: colours, spacing and layout. JavaScript adds behaviour: respond to an event, transform data and update what is displayed. The browser combines these to create the page you use.',why:'Knowing which ingredient owns a change makes unfamiliar project files easier to navigate.',experiment:'Switch the preview between its normal and plain presentation. The transaction data and filtering still work.',task:'You want the filter to respond when a different category is selected. Which ingredient supplies that behaviour?',choices:['CSS','JavaScript','HTML alone'],answer:1,explain:'JavaScript handles the change event and updates the displayed rows. HTML supplies the select element and CSS styles it.',hint:'Think about which ingredient performs actions.',visual:'style'},
 {title:'Data, state and derived values',tag:'Follow a change',time:8,question:'Which things should an application remember?',body:'Data describes the records: a payee, category and amount. Interface state remembers a current choice, such as the selected category. A derived value is calculated from data and state: the visible transactions and their subtotal. Recalculate that subtotal when the selection changes instead of keeping a separate number that could become stale.',why:'Many interface bugs come from storing the same fact in several places and updating only one.',experiment:'Choose Food, then Travel. Compare the selected category, visible rows and subtotal.',task:'Which value is derived from the records and the selected category?',choices:['The selected category','A transaction’s original payee','The subtotal of visible rows'],answer:2,explain:'The subtotal can be calculated from the visible records. The category selection is state; the payee is part of a record.',hint:'Which value can you calculate instead of remembering separately?',visual:'state'},
 {title:'Browser, server, database',tag:'Responsibilities',time:8,question:'Where does a category change go when you save it?',body:'The browser displays the interface and collects your input. An API is a defined way for it to request work from a server, usually using HTTP. A Python backend could validate the request and ask PostgreSQL to store the category change. The server sends a response; the browser then shows the result. React does not replace the backend or database.',why:'A stack is a set of responsibilities. You can understand the boundaries before learning every product.',experiment:'Step through the illustrated save journey. This is a simulation: it does not run Python or PostgreSQL.',task:'Which layer should validate whether a user is allowed to edit a transaction?',choices:['Only the browser','The server','CSS'],answer:1,explain:'The server must enforce authorisation. Browser validation can improve the experience but can be bypassed.',hint:'Which layer must remain trustworthy when a client sends a fabricated request?',visual:'trace'},
 {title:'What survives a refresh?',tag:'Persistence',time:7,question:'Why did my changes disappear?',body:'Values in JavaScript memory usually disappear when the page reloads. Browser localStorage can survive a refresh on the same browser and origin, but may be cleared and does not synchronise across devices. A database behind an API can provide shared persistence. Saving progress in this academy uses localStorage; the finance preview resets on reload.',why:'“The screen changed” and “the change was saved” are different claims.',experiment:'Write a practice note and save it in this browser. Reload the page to check it. This note is separate from your course progress.',task:'Which choice can keep your academy progress after a refresh on this browser, without a backend?',choices:['A local JavaScript variable','A CSS class','localStorage'],answer:2,explain:'localStorage persists text values for this origin. It is not a cross-device account or a substitute for server-side storage.',hint:'Look for a browser storage mechanism.',visual:'storage'},
 {title:'Empty is not an error',tag:'Requests and responses',time:8,question:'How should a screen behave while data is arriving?',body:'A request takes time and can fail. A useful interface distinguishes loading, success with records, success with no records, and failure. An empty list is a valid result. A failed request means you do not yet know what records exist. Never replace a failed response with a reassuring “no transactions” message.',why:'These states make an application understandable when the network is slow or unavailable.',experiment:'Choose a simulated response. Notice that loading, empty and failure have different messages. No network request is made in this illustration.',task:'A request fails. Which message accurately describes what happened?',choices:['You have no transactions','Could not load transactions. Try again.','All transactions saved'],answer:1,explain:'A failed request does not establish that the dataset is empty or that anything was saved.',hint:'Describe what you know, without inventing a successful outcome.',visual:'network'},
 {title:'Values and variables',tag:'JavaScript · 01',time:10,question:'How does code give a name to a value?',body:'A variable binds a name to a value. const amountPence = -1250 stores a number representing a £12.50 outflow. A quoted value such as "1250" is text, not a number. We keep money as integer pence in these exercises and format it as pounds only for display. Negative values are outflows.',why:'A numeric string can produce surprising results: "1250" + 100 becomes "1250100".',experiment:'Edit the code and run it. return sends your answer back to the checker. This is real JavaScript executed in a separate worker.',task:'Create a numeric variable called amountPence for a £25.00 outflow, then return its value.',starter:'const amountPence = 0;\nreturn amountPence;',solution:'const amountPence = -2500;\nreturn amountPence;',hint:'There are 100 pence in a pound. An outflow is negative.',explain:'-2500 is a number representing an outflow of £25.00. No currency symbol or quotes belong in this numeric value.',check:'value',visual:'code'},
 {title:'Objects describe a record',tag:'JavaScript · 02',time:10,question:'How can one value describe a transaction?',body:'An object groups named properties. In { payee: "Corner shop", amountPence: -1250 }, payee and amountPence are keys. transaction.payee reads a property using dot notation. Objects let you keep related facts together rather than maintaining disconnected variables.',why:'A database row, JSON response and JavaScript object can describe the same transaction in different representations.',experiment:'The input tab shows the fictional transaction supplied to your code. Read its properties and return an answer.',task:'Return the payee of transaction. Use the input record so your answer works for other payees too.',starter:'return transaction;',solution:'return transaction.payee;',hint:'Use dot notation: objectName.propertyName.',explain:'transaction.payee reads the property from the supplied object. It also works when a different transaction is supplied.',check:'property',visual:'code'},
 {title:'Arrays hold a collection',tag:'JavaScript · 03',time:10,question:'How do you find a record in a list?',body:'An array is an ordered collection. JavaScript counts positions from zero: transactions[0] is the first record, transactions[1] is the second. The .length property reports the number of items. Position is not a stable identity: sorting changes positions, so real edits should use a transaction ID.',why:'Most finance screens work with collections of records, even when only a few rows are visible.',experiment:'Inspect the four-record input. Try returning transactions.length before completing the task.',task:'Return the payee of the first record in transactions, using the supplied array.',starter:'return transactions.length;',solution:'return transactions[0].payee;',hint:'Read position zero, then read that object’s payee property.',explain:'transactions[0] returns the first object. .payee then reads a property of that object.',check:'array',visual:'code'},
 {title:'Functions turn input into output',tag:'JavaScript · 04',time:12,question:'How do you describe a calculation once and reuse it?',body:'A function has parameters (names for its inputs), a body (its work), and often a return value (its output). function double(value) { return value * 2; } defines a reusable calculation. Calling double(3) gives 6. A function does not return its calculation unless you explicitly return it in this form.',why:'React components, event handlers and data transformations all build on functions.',experiment:'Complete the function. The checker calls it with several positive and negative amounts, not just the displayed example.',task:'Implement toPounds(amountPence), dividing integer pence by 100. Keep the result numeric and preserve its sign.',starter:'function toPounds(amountPence) {\n  return amountPence;\n}\nreturn toPounds;',solution:'function toPounds(amountPence) {\n  return amountPence / 100;\n}\nreturn toPounds;',hint:'Use the division operator /. Returning the function lets the checker try several inputs.',explain:'Dividing by 100 converts pence into pounds. This function returns a number; formatting it as £12.50 is a separate display concern.',check:'function',visual:'code'}
];
